function build(M) {
  const R = 1.05;
  const tyre = M.T(M.torus(0.99, 0.055, 64, 12), {rx: 90});
  const tread = [];
  for (let i = 0; i < 48; i++) {
    const a = i / 48 * Math.PI * 2;
    tread.push(M.T(M.box(0.03, 0.02, 0.07, -0.01), {pos: [Math.cos(a) * 1.04, Math.sin(a) * 1.04, 0], rz: a * 180 / Math.PI - 90}));
  }
  const rim = M.T(M.lathe([[0.9, -0.025], [0.94, -0.03], [0.94, 0.03], [0.9, 0.025]], 64), {rx: 90});
  const spokes = [];
  for (let i = 0; i < 32; i++) {
    const a = i / 32 * Math.PI * 2, b = a + (i % 2 ? 0.25 : -0.25);
    const z = i % 2 ? 0.035 : -0.035;
    spokes.push(M.pipe([Math.cos(b) * 0.05, Math.sin(b) * 0.05, z], [Math.cos(a) * 0.9, Math.sin(a) * 0.9, 0], 0.006, 4));
  }
  const hub = M.T(M.lathe([[0.02, -0.045], [0.06, -0.045], [0.06, -0.03], [0.03, -0.025], [0.03, 0.025], [0.06, 0.03], [0.06, 0.045], [0.02, 0.045]], 24), {rx: 90});
  const axle = M.T(M.cyl(0.012, 0.12, 12, -0.06), {rx: 90});
  return [
    {material: "dark_steel", look: "solid", mesh: M.merge([tyre, ...tread])},
    {material: "steel", look: "solid", mesh: M.merge([rim, ...spokes, hub])},
    {material: "gold", look: "solid", mesh: axle}
  ];
}

function build(M) {
  const rx = 90;
  const tyre = M.T(M.torus(0.99, 0.055, 64, 12), {rx});
  const treads = [];
  for (let i = 0; i < 60; i++) {
    const a = i * 6 * Math.PI / 180;
    treads.push(M.T(M.box(0.02, 0.025, 0.07, -0.0125), {pos: [Math.cos(a) * 1.04, Math.sin(a) * 1.04, 0], rz: i * 6 - 90}));
  }
  const rim = M.T(M.lathe([[0.9, -0.03], [0.94, -0.035], [0.94, 0.035], [0.9, 0.03]], 64), {rx});
  const spokes = [];
  for (let i = 0; i < 32; i++) {
    const a = i * Math.PI * 2 / 32;
    const side = i % 2 ? 0.035 : -0.035;
    spokes.push(M.pipe([Math.cos(a) * 0.05, Math.sin(a) * 0.05, side], [Math.cos(a) * 0.9, Math.sin(a) * 0.9, 0], 0.006, 4));
  }
  const hub = M.merge([
    M.T(M.cyl(0.035, 0.12, 24, -0.06), {rx}),
    M.T(M.cyl(0.06, 0.01, 24, -0.045), {rx}),
    M.T(M.cyl(0.06, 0.01, 24, 0.035), {rx})
  ]);
  const gears = [];
  for (let g = 0; g < 5; g++) {
    const R = 0.17 - g * 0.025, n = 28 - g * 4, pts = [];
    for (let k = 0; k < n * 2; k++) {
      const a = k * Math.PI / n, r = k % 2 ? R : R - 0.012;
      pts.push([Math.cos(a) * r, Math.sin(a) * r]);
    }
    gears.push(M.T(M.extrude(pts, 0.006), {rx, pos: [0, 0, 0.012 + g * 0.009]}));
  }
  return [
    {material: "dark_steel", look: "solid", mesh: M.merge([tyre, ...treads])},
    {material: "steel", look: "solid", mesh: M.merge([rim, ...spokes, hub])},
    {material: "dark_steel", look: "solid", mesh: M.merge(gears)}
  ];
}

function build(M) {
  const pts = [];
  for (let i = 0; i <= 24; i++) {
    const t = i / 24, x = -0.4 + 0.8 * t;
    const w = t < 0.4 ? 0.2 * Math.sqrt(1 - Math.pow((0.4 - t) / 0.4, 2) * 0.6) : 0.2 - (t - 0.4) / 0.6 * 0.16;
    pts.push([x, w]);
  }
  const outline = pts.map(p => [p[0], p[1]]).concat(pts.slice().reverse().map(p => [p[0], -p[1]]));
  const top = M.T(M.extrude(outline, 0.07), {pos: [0, 0.155, 0]});
  const shell = M.T(M.extrude(outline.map(p => [p[0] * 0.97, p[1] * 0.92]), 0.03), {pos: [0, 0.11, 0]});
  const rails = [];
  for (const z of [-0.05, 0.05]) {
    rails.push(M.pipe([-0.28, 0.1, z * 1.6], [-0.18, 0.04, z], 0.008, 10));
    rails.push(M.pipe([-0.18, 0.04, z], [0.18, 0.04, z], 0.008, 10));
    rails.push(M.pipe([0.18, 0.04, z], [0.33, 0.1, z * 0.5], 0.008, 10));
  }
  const clamp = M.merge([M.box(0.07, 0.04, 0.14, 0.0), M.T(M.cyl(0.012, 0.16, 12, -0.08), {pos: [0, 0.03, 0], rx: 90})]);
  const logo = M.T(M.box(0.12, 0.004, 0.06, 0.19), {pos: [-0.2, 0, 0]});
  return [
    {material: "dark_steel", look: "solid", mesh: top},
    {material: "concrete", look: "solid", mesh: shell},
    {material: "steel", look: "solid", mesh: M.merge(rails)},
    {material: "dark_steel", look: "solid", mesh: clamp},
    {material: "red", look: "solid", mesh: logo}
  ];
}

function build(M) {
  const R = 0.3, out = [];
  for (let i = 0; i < 40; i++) {
    const a = i / 40 * Math.PI * 2, b = a + Math.PI / 40, c = a + Math.PI / 20;
    out.push([Math.cos(a) * R, Math.sin(a) * R], [Math.cos(b) * (R + 0.03), Math.sin(b) * (R + 0.03)]);
  }
  const ring = M.T(M.extrude(out, 0.02), {rx: 90, pos: [0, 0, 0.1]});
  const inner = M.T(M.torus(0.22, 0.015, 40, 8), {rx: 90, pos: [0, 0, 0.11]});
  const spokes = [];
  for (let i = 0; i < 5; i++) {
    const a = i / 5 * Math.PI * 2;
    spokes.push(M.pipe([0, 0, 0.1], [Math.cos(a) * 0.22, Math.sin(a) * 0.22, 0.1], 0.02, 8));
  }
  const bolts = [];
  for (let i = 0; i < 5; i++) {
    const a = i / 5 * Math.PI * 2 + 0.6;
    bolts.push(M.T(M.cyl(0.015, 0.02, 12, 0), {rx: 90, pos: [Math.cos(a) * 0.2, Math.sin(a) * 0.2, 0.13]}));
  }
  const L = 0.32, ang = 50 * Math.PI / 180;
  const ex = Math.cos(ang) * L, ey = Math.sin(ang) * L;
  const arm1 = M.pipe([0, 0, 0.14], [ex, ey, 0.14], 0.03, 12);
  const arm2 = M.pipe([0, 0, -0.14], [-ex, -ey, -0.14], 0.03, 12);
  const axle = M.T(M.cyl(0.04, 0.32, 20, -0.16), {rx: 90});
  const pedal = (x, y, z0) => {
    const p = [M.T(M.box(0.2, 0.04, 0.24, -0.02), {pos: [x, y, z0]})];
    for (const dx of [-0.1, 0.1]) p.push(M.T(M.box(0.02, 0.06, 0.24, -0.03, dx), {pos: [x, y, z0]}));
    return p;
  };
  const pedals = [...pedal(ex, ey, 0.32), ...pedal(-ex, -ey, -0.32)];
  const spindles = [M.pipe([ex, ey, 0.14], [ex, ey, 0.2], 0.012, 8), M.pipe([-ex, -ey, -0.14], [-ex, -ey, -0.2], 0.012, 8)];
  return [
    {material: "steel", look: "solid", mesh: M.merge([ring, inner, ...spokes, ...spindles])},
    {material: "dark_steel", look: "solid", mesh: M.merge([arm1, arm2, axle, ...pedals])},
    {material: "gold", look: "solid", mesh: M.merge(bolts)}
  ];
}
